package com.wanderwise.api;
import com.wanderwise.model.*;import com.wanderwise.repo.SavedTripRepository;import com.wanderwise.service.*;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api")
public class TravelController {
 private final RecommendationService recommendations;private final ExternalTravelService external;private final SavedTripRepository trips;
 public TravelController(RecommendationService r,ExternalTravelService e,SavedTripRepository t){recommendations=r;external=e;trips=t;}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","app","WanderWise");}
 @GetMapping("/destinations") public List<Destination> destinations(){return TravelData.DESTINATIONS;}
 @GetMapping("/recommendations") public Map<String,Object> recommend(@RequestParam(defaultValue="0") long budget,@RequestParam(defaultValue="3") @Min(1) @Max(30) int days,@RequestParam(defaultValue="2") @Min(1) @Max(20) int travellers,@RequestParam(required=false) List<String> preferences,@RequestParam(defaultValue="Any") String style){List<Map<String,Object>> results=recommendations.recommend(budget,days,travellers,preferences,style);return Map.of("count",results.size(),"results",results,"budgetBasis","Total trip budget divided by days and travellers; estimated daily per-person destination cost.");}
 @GetMapping("/weather/{id}") public Object weather(@PathVariable String id){return external.weather(find(id));}
 @GetMapping("/places/{id}") public Map<String,Object> places(@PathVariable String id,@RequestParam(defaultValue="all") String category){return Map.of("destination",find(id).name(),"category",category,"source","OpenStreetMap contributors","results",external.places(find(id),category));}
 @GetMapping("/transport-links/{id}") public Map<String,Object> transport(@PathVariable String id){Destination d=find(id);String q=java.net.URLEncoder.encode(d.name()+" "+d.state(),java.nio.charset.StandardCharsets.UTF_8);return Map.of("destination",d.name(),"options",List.of(Map.of("name","Public transport & local routes","url","https://www.google.com/maps/dir/?api=1&destination="+q,"kind","Directions"),Map.of("name","Train search","url","https://www.irctc.co.in/nget/train-search","kind","Rail"),Map.of("name","Bus search","url","https://www.redbus.in/","kind","Bus"),Map.of("name","Flight search","url","https://www.google.com/travel/flights?q=flights%20to%20"+q,"kind","Air"),Map.of("name","Car rental search","url","https://www.google.com/search?q=car+rentals+in+"+q,"kind","Car")));}
 @GetMapping("/booking-links/{id}") public Map<String,Object> bookings(@PathVariable String id){Destination d=find(id);String q=java.net.URLEncoder.encode(d.name()+" hotels",java.nio.charset.StandardCharsets.UTF_8);return Map.of("destination",d.name(),"links",List.of(Map.of("name","Booking.com","url","https://www.booking.com/searchresults.html?ss="+q),Map.of("name","Agoda","url","https://www.agoda.com/search?city="+q),Map.of("name","Google Hotels","url","https://www.google.com/travel/hotels/"+q),Map.of("name","Restaurant search","url","https://www.google.com/maps/search/restaurants+in+"+q)));}
 @GetMapping("/trips") public List<SavedTrip> allTrips(){return trips.findAll();}
 public record TripRequest(@NotBlank String destinationId,@Min(1) @Max(30) int days,@Min(1) @Max(20) int travellers,@PositiveOrZero long totalBudget,String preferences,String startDate){}
 @PostMapping("/trips") @ResponseStatus(HttpStatus.CREATED) public SavedTrip save(@RequestBody @jakarta.validation.Valid TripRequest r){Destination d=find(r.destinationId());return trips.save(new SavedTrip(d.id(),d.name(),r.days(),r.travellers(),r.totalBudget(),r.preferences(),r.startDate()));}
 @DeleteMapping("/trips/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){if(!trips.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Trip not found");trips.deleteById(id);}
 private Destination find(String id){return TravelData.byId(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Destination not found"));}
}
